-- 6. Staging records: 500 to be approved into core,
--    500 staying in the staging review workflow
--    (1000 total staging rows once approvals below run)
INSERT INTO staging.research_objects(
    staging_id, title, description, abstract, output_type_id, department_id, year,
    publisher, language, identifier, external_url, rights, access_level, workflow_status,
    created_by, submitted_by, submitted_at, reviewed_by, reviewed_at, approved_by, approved_at,
    rejection_reason, revision_note
)
SELECT v.staging_id::uuid, v.title, v.description, v.abstract, ot.output_type_id, d.department_id, v.year,
       v.publisher, v.language, v.identifier, v.external_url, v.rights, v.access_level::app.access_level,
       v.workflow_status::app.workflow_status, cu.user_id, su.user_id, v.submitted_at::timestamptz,
       ru.user_id, v.reviewed_at::timestamptz, au.user_id, v.approved_at::timestamptz,
       v.rejection_reason, v.revision_note
FROM (VALUES
    ('c53e32ec-43e7-48bf-a947-7fb5c4b289d8', 'Research on ground improvement Combined with foundation engineering', 'Sản phẩm nghiên cứu của Khoa Kỹ thuật Công trình, khai thác hướng ground improvement kết hợp với foundation engineering.', 'This research project investigates ground improvement in relation to foundation engineering. Using an experimental investigation of, the work analyzes current practices under real-world operating conditions and proposes recommendations to improve outcomes. The findings contribute to the growing body of knowledge on ground improvement and offer practical implications for practitioners and researchers alike.', 'RESEARCH_PROJECT', 'KTCT', 2023, 'Phòng Khoa học Công nghệ - STU', 'en', 'RDMS-SEED-CORE-0001', 'https://example.edu.vn/rdms-seed/rdms-seed-core-0001', 'Bản quyền thuộc về tác giả và STU', 'public', 'pending_approval', 'dataentry_ktct', 'dataentry_ktct', '2023-10-13', 'reviewer_ktct', '2023-10-17', 'approver_ktct', NULL, NULL, NULL),
    ('a4d51522-3e9d-4a0e-8546-11cec59bea5a', 'Evidence Report on food preservation Implementation in an urban Vietnamese setting', 'Công trình do giảng viên Khoa Công nghệ Thực phẩm thực hiện, hướng đến giải quyết vấn đề food preservation trong bối cảnh thực tế.', 'This evidence document presents a systematic review of food preservation, with particular attention to food product development. Data were collected and analyzed for industry 4.0 applications, revealing several key insights that extend existing understanding of food preservation. The results are expected to support future work in this domain.', 'EVIDENCE_DOCUMENT', 'CNTP', 2024, 'Phòng Khoa học Công nghệ - STU', 'en', 'RDMS-SEED-CORE-0002', 'https://example.edu.vn/rdms-seed/rdms-seed-core-0002', 'Bản quyền thuộc về tác giả và STU', 'internal', 'pending_approval', 'dataentry_cntp', 'dataentry_cntp', '2024-09-05', 'reviewer_cntp', '2024-09-12', 'approver_cntp', NULL, NULL, NULL),
