-- 11. Refresh metadata quality scores for all seeded staging records
DO $$
DECLARE
    rec RECORD;
BEGIN
    FOR rec IN
        SELECT staging_id
        FROM staging.research_objects
        WHERE identifier LIKE 'RDMS-SEED-%'
    LOOP
        PERFORM app.refresh_staging_metadata_quality(rec.staging_id);
    END LOOP;
END $$;

