JOIN auth.users u ON u.username = v.performed_by;

-- 13. Approve the 500 core-bound staging records through app.approve_staging_record()
--     This keeps the staging mirror row (status='approved') as required.
DO $$
DECLARE
    rec RECORD;
BEGIN
    FOR rec IN
        SELECT s.staging_id, s.approved_by
        FROM staging.research_objects s
        WHERE s.identifier LIKE 'RDMS-SEED-CORE-%'
          AND s.workflow_status = 'pending_approval'
    LOOP
        PERFORM app.approve_staging_record(rec.staging_id, rec.approved_by, 'Duyet ho so du lieu seed vao core');
    END LOOP;
END $$;
